local RpcClient = Object:new({
	__type = 'RpcClient',
})

--初始化RPC连接
function RpcClient:init(ip,port,timeout,ssl)
	if (ssl == true) then
		socket = TSocketSSL:new{
			host = ip,
			port = port
		 }
	else
		socket = TSocket:new{
			host = ip,
			port = port
		}
	end
	socket:setTimeout(timeout)
	local transport = TFramedTransport:new{
		trans = socket
	}
	local protocol = TBinaryProtocol:new{
		trans = transport
	}
	transport:open()
	return protocol;
