    .:53 {
        errors
        health {
           lameduck 5s
        }
        ready
        template ANY ANY user-service.social-network.svc.cluster.local {
            match "^user-service.social-network.svc.cluster.local\.$"
            rcode NXDOMAIN
            fallthrough
        }
        kubernetes cluster.local in-addr.arpa ip6.arpa {
           pods insecure
           fallthrough in-addr.arpa ip6.arpa
           ttl 30
        }
        prometheus :9153
        forward . /etc/resolv.conf {
           max_concurrent 1000
        }
        cache 30 {
           disable success cluster.local
           disable denial cluster.local
        }
        loop
        reload
        loadbalance
    }
